# English · teacher's edition (translation of lecciones.py; keys are QWERTY, as in the English lessons).
S = 'https://musicmotionsuite.com'
def a(u, t): return f'<a href="{u}">{t}</a>'
def k(x): return ''.join(f'<span class="k">{c}</span>' for c in x.split())
KB = a(S + '/apps/mmk-demo.html', 'Keyboard')
AF = a('https://tuner.mariomaurano.com', 'tuner')
MM = a(S + '/suite/tragamonedas.html?lang=en', 'melody machine')
ARM = a(S + '/suite/armonia-maquina.html?lang=en', 'harmony machine')
SC = S + '/apps/mm-score-page.html?demo&file=../suite/demos/'
EST = a(SC + 'estrellita.mmf&page', '“Twinkle, Twinkle, Little Star”')
SEI = a(SC + 'seikilos.mmf&page', 'the Song of Seikilos')
E1 = 'ages 8 to 12'; E2 = 'ages 9 to 14'
T = {}

T['n1c2'] = dict(titulo='High and low, long and short', lema='High and low, long and short sounds', edad=E1, gram_ref='ch. 2, pp. 8–11',
  gram_desc='“High and low, long and short” (pp. 8 and 9), the sounds of the reed and your straw panpipe (pp. 10 and 11).',
  meta='Each pair <b>reads a drawing of three or four lines on the board</b> (high or low, short or long) <b>and plays it on the keyboard</b>; the class confirms with a thumbs-up whether it sounded like the drawing. Also: show with the body whether a sound is high or low, and count with the beat how many clicks a long sound lasts.',
  necesita='A computer with a speaker, the board (and a projector, if possible) and <b>four identical glasses of water and a spoon</b>. It helps to have done Lesson 1. No musical knowledge needed: the keyboard does the work; you guide.',
  antes=[f'Open the {KB}: press {k("Z")} and then {k("U")}; the first is low, the second high.', f'Play {k("Z X C V B N M")}, press {k("←")} twice and play again: the whole staircase goes down. {k("→")} twice brings you back.', 'Open <b>pulse</b> at about 60 BPM, with <b>start</b> and <b>click</b>, as in Lesson 1.', f'With the metronome: {k("Z")} released at once (one click) and {k("Z")} held down for four clicks.'],
  etapas_t=[('The goal', '<i>“Today we are going to learn to draw a sound and play a drawing.”</i> On the board: <b>I can draw a sound and play a drawing.</b>'),
   ('What they already know: the staircase and the beat', f'With a slow metronome, the staircase {k("Z")}…{k("M")}, one key per click; the class sings each note on “ah” and taps the beat with their feet. <i>“Does the staircase go up or down?”</i>'),
   ('New material: high and low, long and short', f'<b>The lift</b>: crouching for low ({k("Z")}), standing for high ({k("U")}). <b>The singing glasses</b>: which glass sounds lowest? <b>The same song high and low</b>, with {k("←")} and {k("→")}. <b>Long and short</b>: one click is a clap; four clicks, the arms open slowly.'),
   ('Application: drawing the sound and playing the drawing', 'On the board, the line of the “middle floor”: high above it, low below it; short, a short line; long, a long line. <b>Drawing</b>: you play, a pupil draws. <b>Playing the drawing</b>: the example ' + k('Z C B') + ' and ' + k('Z') + ' for four clicks, <i>ta · ta · ta · taaaa</i>; then a pair: one points, the other plays, and the class gives a thumbs-up.'),
   ('Reviewing the goal', 'A last drawing of four lines for the pairs who have not had a turn. <i>“How did you know whether a line went up or down? And whether it was long or short?”</i>')],
  cuesta=f'They confuse high with loud: sing the same note softly and loudly, it is the same pitch; then {k("Z")} and {k("U")}. They can’t hear two close notes: start with notes far apart. They let go too soon: count the clicks aloud. The drawing doesn’t match: line by line, slowly.',
  funciono='At least <b>3 out of 4 pairs</b> play the drawing with the right pitch and length; most show with the body whether a sound is high or low and count the clicks of a long sound correctly.',
  final_t='At the end, for fun', final=f'The {MM}, with Tempo around 80: the lift with the hand, clapping and opening the arms with PLAY, and the game <b>Up or down?</b>',
  eval_que='Pairs who played the drawing', eval_si_no='start Lesson 3 with a three-line drawing on the board (5 min).',
  palabras=[('High', 'A thin, bright sound, like a bird or a whistle. On the keyboard, towards the top row.'), ('Low', 'A thick, deep sound, like thunder or a double bass. On the keyboard, towards the bottom row.'),
   ('Pitch', 'Whether a sound is high or low. It is not the volume: high and low do not mean loud and soft.'), ('Volume', 'Whether a sound is loud or soft. In this lesson it does not change.'),
   ('Long and short', 'How long a sound lasts. Short: one click, “ta”. Long: several clicks, “taaaa”.'), ('The octave', 'The same staircase higher or lower. The arrows ← and → change it.'),
   ('Drawing the sound', 'A line above or below the line, short or long: the grandfather of the score.'), ('Neumes', 'The signs medieval monks used to draw the melody, before the stave.')])

